import {clsx} from 'clsx'
import type {ComponentPropsWithoutRef} from 'react'

import styles from './DatumText.module.css'

export function DatumText({children, className, ...props}: ComponentPropsWithoutRef<'span'>) {
  return (
    <span className={clsx(styles.DatumText, className)} {...props}>
      {children}
    </span>
  )
}
