import type {Language} from '../../types'

import styles from './LanguagesWithColor.module.css'

interface LanguageWithColorProps {
  languages: Language[]
}

export function LanguagesWithColor({languages}: LanguageWithColorProps) {
  return (
    <div className={styles.LanguagesWithColor}>
      {languages.map(language => (
        <div key={language.id} className={styles.languageItem}>
          <div className={styles.colorDot} style={{backgroundColor: language.color}} />
          <div className={styles.languageName}>
            <span className={styles.nameText}>{language.name}</span>
          </div>
        </div>
      ))}
    </div>
  )
}
